/**
 * Windows-safe bounded JSON persistence shared by in-house DSH plugins.
 *
 * Combines:
 *   - Bounded non-blocking fd read (`readJsonFileBoundedSync`) that refuses
 *     directories, FIFOs, and oversized files;
 *   - Unique temporary file (`wx` exclusive open) + atomic rename + Windows
 *     `EPERM`/`EEXIST` `.bak` fallback + `finally` temp cleanup;
 *   - Self-cleaning per-path async write queue (`enqueueFileWrite`) so
 *     concurrent saves never interleave or leak Map entries.
 *
 * THIS FILE IS THE SOURCE OF TRUTH. Copies in plugins are generated by
 * `tools/sync-shared-code.mjs` and must stay byte-identical.
 *
 * ASCII only: see the workspace AGENTS.md encoding rule.
 */

import * as fs from 'node:fs'
import * as fsp from 'node:fs/promises'
import { randomBytes } from 'node:crypto'
import { dirname } from 'node:path'

/** Default ceiling for bounded state/config reads (256 KiB). */
export const DEFAULT_MAX_JSON_BYTES = 256 * 1024

const WRITE_QUEUES = new Map()

function isAcceptableRegularFile(info, maxBytes) {
  return info.isFile() && Number.isSafeInteger(info.size) && info.size >= 0 && info.size <= maxBytes
}

/**
 * Synchronously read and parse a JSON file with strict size and file-type bounds.
 * Returns `fallback` if missing, oversized, non-regular, or invalid JSON.
 *
 * @param {string} file
 * @param {{maxBytes?: number, fallback?: unknown, io?: typeof fs}} [options]
 * @returns {unknown}
 */
export function readJsonFileBoundedSync(file, options = {}) {
  const maxBytes = options.maxBytes ?? DEFAULT_MAX_JSON_BYTES
  const fallback = options.fallback
  const io = options.io ?? fs
  const capacity = maxBytes + 1
  let fd
  try {
    if (!isAcceptableRegularFile(io.statSync(file), maxBytes)) return fallback
    const flags = io.constants?.O_RDONLY !== undefined
      ? io.constants.O_RDONLY | (io.constants.O_NONBLOCK ?? 0)
      : fs.constants.O_RDONLY | (fs.constants.O_NONBLOCK ?? 0)
    fd = io.openSync(file, flags)
    if (!isAcceptableRegularFile(io.fstatSync(fd), maxBytes)) return fallback
    const buffer = Buffer.alloc(capacity)
    let total = 0
    for (let attempt = 0; attempt < capacity; attempt += 1) {
      const remaining = capacity - total
      const count = io.readSync(fd, buffer, total, remaining, null)
      if (!Number.isInteger(count) || count < 0 || count > remaining) return fallback
      if (count === 0) return JSON.parse(buffer.toString('utf8', 0, total))
      total += count
      if (total > maxBytes) return fallback
    }
    return fallback
  } catch {
    return fallback
  } finally {
    if (fd !== undefined) {
      try { io.closeSync(fd) } catch { /* best effort */ }
    }
  }
}

function uniqueTmpPath(file) {
  return `${file}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`
}

/**
 * Synchronously write JSON via exclusive temp file + atomic rename with Windows
 * `EPERM`/`EEXIST` `.bak` swap fallback and guaranteed temp cleanup.
 *
 * @param {string} file
 * @param {unknown} value
 * @param {{spaces?: number}} [options]
 */
export function writeJsonAtomicSync(file, value, options = {}) {
  const spaces = options.spaces ?? 2
  const payload = spaces > 0 ? `${JSON.stringify(value, null, spaces)}\n` : JSON.stringify(value)
  fs.mkdirSync(dirname(file), { recursive: true })
  const tmp = uniqueTmpPath(file)
  let fd
  try {
    fd = fs.openSync(tmp, 'wx', 0o600)
    fs.writeFileSync(fd, payload, 'utf8')
    fs.closeSync(fd)
    fd = undefined
    try {
      fs.renameSync(tmp, file)
    } catch (error) {
      if (error && (error.code === 'EPERM' || error.code === 'EEXIST' || error.code === 'EACCES')) {
        const bak = `${file}.${process.pid}.bak`
        try { fs.unlinkSync(bak) } catch { /* ignore */ }
        let movedOld = false
        try {
          if (fs.existsSync(file)) {
            fs.renameSync(file, bak)
            movedOld = true
          }
          fs.renameSync(tmp, file)
          try { fs.unlinkSync(bak) } catch { /* ignore */ }
        } catch (swapError) {
          if (movedOld && !fs.existsSync(file)) {
            try { fs.renameSync(bak, file) } catch { /* ignore */ }
          }
          throw swapError
        }
      } else {
        throw error
      }
    }
  } finally {
    if (fd !== undefined) {
      try { fs.closeSync(fd) } catch { /* ignore */ }
    }
    try { fs.unlinkSync(tmp) } catch { /* ignore */ }
  }
}

/**
 * Serialize async operations targeting the same file path. Settled chains are
 * evicted automatically so the internal Map does not grow without bound.
 *
 * @template T
 * @param {string} file
 * @param {() => Promise<T>} work
 * @returns {Promise<T>}
 */
export function enqueueFileWrite(file, work) {
  const previous = WRITE_QUEUES.get(file) ?? Promise.resolve()
  const current = previous.catch(() => {}).then(() => work())
  const tracked = current.finally(() => {
    if (WRITE_QUEUES.get(file) === tracked) WRITE_QUEUES.delete(file)
  })
  WRITE_QUEUES.set(file, tracked)
  return current
}

/**
 * Asynchronously write JSON via exclusive temp file + atomic rename with
 * Windows `EPERM`/`EEXIST` `.bak` fallback, temp cleanup, and per-path queue.
 *
 * @param {string} file
 * @param {unknown} value
 * @param {{spaces?: number}} [options]
 */
export function writeJsonAtomic(file, value, options = {}) {
  const spaces = options.spaces ?? 2
  const payload = spaces > 0 ? `${JSON.stringify(value, null, spaces)}\n` : JSON.stringify(value)
  return enqueueFileWrite(file, async () => {
    await fsp.mkdir(dirname(file), { recursive: true })
    const tmp = uniqueTmpPath(file)
    try {
      const handle = await fsp.open(tmp, 'wx', 0o600)
      try {
        await handle.writeFile(payload, 'utf8')
      } finally {
        await handle.close()
      }
      try {
        await fsp.rename(tmp, file)
      } catch (error) {
        if (error && (error.code === 'EPERM' || error.code === 'EEXIST' || error.code === 'EACCES')) {
          const bak = `${file}.${process.pid}.bak`
          await fsp.unlink(bak).catch(() => {})
          let movedOld = false
          try {
            try {
              await fsp.rename(file, bak)
              movedOld = true
            } catch (e) {
              if (!e || e.code !== 'ENOENT') throw e
            }
            await fsp.rename(tmp, file)
            await fsp.unlink(bak).catch(() => {})
          } catch (swapError) {
            if (movedOld) {
              await fsp.rename(bak, file).catch(() => {})
            }
            throw swapError
          }
        } else {
          throw error
        }
      }
    } finally {
      await fsp.unlink(tmp).catch(() => {})
    }
  })
}
